window.SLP = window.SLP || { books: [], gloss: [] }; var SLP = window.SLP;
var _ac = SLP.books.find(function(b){ return b.id === "acts"; });
if (!_ac) throw new Error("data/canon.js must load before nt-04-acts.js");
(_ac.chapters = _ac.chapters || []).push(
  { n:1, summary:"Luke addresses Theophilus and recalls his earlier Gospel, then follows the risen Jesus through forty days of teaching about the kingdom of God. The Lord commands the apostles not to leave Jerusalem but to wait for the promise of the Father, a baptism with the Holy Ghost. When they ask whether He will now restore the kingdom to Israel, He answers that the timing belongs to the Father, but they will receive power and be His witnesses in Jerusalem, Judea, Samaria, and to the uttermost part of the earth. He ascends before their eyes, and two men in white promise He will return in like manner. Back in Jerusalem, about one hundred twenty disciples pray in an upper room. Peter explains Judas's fall from scripture, the disciples pray, and by lot Matthias is numbered with the eleven apostles.",
    context:"Luke writes to Theophilus as the sequel to his Gospel, following the risen Christ's forty days, ascension, and the apostles' waiting in Jerusalem; traditionally dated between about A.D. 62 and 85.",
    keyVerses:[
      { ref:"Acts 1:8", text:"But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judæa, and in Samaria, and unto the uttermost part of the earth." },
      { ref:"Acts 1:9", text:"And when he had spoken these things, while they beheld, he was taken up; and a cloud received him out of their sight." },
      { ref:"Acts 1:11", text:"Which also said, Ye men of Galilee, why stand ye gazing up into heaven? this same Jesus, which is taken up from you into heaven, shall so come in like manner as ye have seen him go into heaven." }
    ],
    takeaway:"The Lord's witnesses receive power through the Holy Ghost, from Jerusalem to the uttermost part of the earth.",
    quiz:[
      { q:"How many days did Jesus show himself alive to the apostles before he was taken up?", choices:["Forty","Three","Twelve","One hundred"], a:0, why:"Acts 1:3 says he was seen of them forty days, speaking of things pertaining to the kingdom of God." },
      { q:"Who was chosen to fill the place in the ministry and apostleship from which Judas fell?", choices:["Joseph called Barsabas, who was surnamed Justus","Matthias","Stephen","Barnabas"], a:1, why:"They appointed two, prayed, and gave forth their lots; the lot fell upon Matthias, and he was numbered with the eleven apostles." },
      { q:"What did Jesus promise the disciples would follow the Holy Ghost coming upon them?", choices:["Riches to fund the work","Relief from all persecution","Power to be his witnesses in Jerusalem, Judea, Samaria, and to the uttermost part of the earth","A written record of all his sayings"], a:2, why:"Jesus said they would receive power after the Holy Ghost came upon them and would be witnesses unto him in ever-widening circles." }
    ] },
  { n:2, summary:"On Pentecost the disciples, gathered in one place, hear a sound like a rushing mighty wind and see cloven tongues like fire; all are filled with the Holy Ghost and speak in other languages. Devout Jews from every nation hear the wonderful works of God in their own tongues, while some mock that the speakers are drunk. Peter, standing with the eleven, explains from the prophet Joel that God is pouring out His Spirit, then testifies that Jesus of Nazareth, delivered up and crucified, God raised from the dead and made both Lord and Christ. The hearers are pricked in heart and ask what to do; Peter calls them to repent and be baptized for the remission of sins and the gift of the Holy Ghost. About three thousand are baptized that day, and the new believers continue in doctrine, fellowship, breaking of bread, prayers, and sharing all things in common.",
    context:"Peter preaches to Jews gathered at Jerusalem for the day of Pentecost, after the Holy Ghost falls on the disciples in an upper room.",
    keyVerses:[
      { ref:"Acts 2:4", text:"And they were all filled with the Holy Ghost, and began to speak with other tongues, as the Spirit gave them utterance." },
      { ref:"Acts 2:36", text:"Therefore let all the house of Israel know assuredly, that God hath made that same Jesus, whom ye have crucified, both Lord and Christ." },
      { ref:"Acts 2:38", text:"Then Peter said unto them, Repent, and be baptized every one of you in the name of Jesus Christ for the remission of sins, and ye shall receive the gift of the Holy Ghost." }
    ],
    takeaway:"God pours out His Spirit on all who repent and are baptized in the name of Jesus Christ, and adds them to His church.",
    quiz:[
      { q:"What sound from heaven filled all the house on the day of Pentecost?", choices:["A sound as of a rushing mighty wind","Loud thunder","A trumpet blast","Voices singing in Hebrew"], a:0, why:"Acts 2:2 says suddenly there came a sound from heaven as of a rushing mighty wind, and it filled all the house where they were sitting." },
      { q:"Which prophet did Peter quote to explain the outpouring of the Spirit?", choices:["Isaiah","Joel","Malachi","Ezekiel"], a:1, why:"Peter said, This is that which was spoken by the prophet Joel, about God pouring out his Spirit upon all flesh." },
      { q:"When the crowd was pricked in heart and asked what to do, what did Peter command?", choices:["Bring sacrifices to the temple","Withdraw into the wilderness","Wait for the kingdom of Israel to be restored","Repent and be baptized every one in the name of Jesus Christ for the remission of sins"], a:3, why:"Peter answered their question with repentance and baptism in the name of Jesus Christ, promising the gift of the Holy Ghost; about three thousand were baptized that day." }
    ] },
  { n:3, summary:"Peter and John go up to the temple at the hour of prayer and meet a man lame from his mother's womb who begs at the Beautiful gate. Peter has no silver or gold, but in the name of Jesus Christ of Nazareth he commands the man to rise and walk, and the man enters the temple leaping and praising God. As a wondering crowd gathers in Solomon's porch, Peter turns their amazement into a sermon: they had denied the Holy One and killed the Prince of life, whom God raised from the dead, and faith in His name made the man strong. He calls them to repent and be converted so their sins may be blotted out when times of refreshing come, citing Moses and the prophets, who foretold that through Abraham's seed all kindreds of the earth would be blessed.",
    context:"In Jerusalem, Peter preaches to a crowd in Solomon's porch after healing a lame beggar at the temple's Beautiful gate at the hour of prayer.",
    keyVerses:[
      { ref:"Acts 3:6", text:"Then Peter said, Silver and gold have I none; but such as I have give I thee: In the name of Jesus Christ of Nazareth rise up and walk." },
      { ref:"Acts 3:15", text:"And killed the Prince of life, whom God hath raised from the dead; whereof we are witnesses." },
      { ref:"Acts 3:19", text:"Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of the Lord;" }
    ],
    takeaway:"Faith in the name of Jesus Christ can do what silver and gold cannot; repentance brings sins blotted out.",
    quiz:[
      { q:"At which gate of the temple did the lame man sit daily asking alms?", choices:["The Beautiful gate","The eastern gate","The sheep gate","Solomon's gate"], a:0, why:"The man lame from his mother's womb was laid daily at the gate of the temple which is called Beautiful." },
      { q:"According to Peter's sermon, what made the lame man strong and whole?", choices:["The alms he had collected over the years","Peter's personal holiness and power","The name of Jesus Christ and faith in that name","The people's wonder and amazement"], a:2, why:"Peter told the crowd he had not healed the man by his own power; his name through faith in his name had given the man perfect soundness." },
      { q:"Whom did Peter say Moses foretold the Lord would raise up, whom Israel must hear?", choices:["A judge to rule Rome's enemies","A priest after Aaron's order","An angel with a new law","A prophet like unto Moses"], a:3, why:"Peter quoted Moses: A prophet shall the Lord your God raise up unto you of your brethren, like unto me; him shall ye hear in all things." }
    ] },
  { n:4, summary:"As Peter and John preach, the priests, the captain of the temple, and the Sadducees arrest them for teaching that Jesus rose from the dead, though the number of believers grows to about five thousand men. The next day the council asks by what power or name they acted, and Peter, filled with the Holy Ghost, answers that the lame man stands whole by the name of Jesus Christ of Nazareth, the stone the builders rejected, in whom alone is salvation. Seeing their boldness and the healed man standing there, the rulers can only threaten them not to speak in that name. The two answer that they cannot but speak what they have seen and heard, and the church responds with a prayer for boldness that shakes the place where they gather. The believers are of one heart and soul, sharing possessions, and Barnabas sells land and lays the price at the apostles' feet.",
    context:"The day after the healing, Peter and John answer the council of rulers, elders, and scribes in Jerusalem, before Annas and Caiaphas and the kindred of the high priest.",
    keyVerses:[
      { ref:"Acts 4:12", text:"Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved." },
      { ref:"Acts 4:19", text:"But Peter and John answered and said unto them, Whether it be right in the sight of God to hearken unto you more than unto God, judge ye." },
      { ref:"Acts 4:20", text:"For we cannot but speak the things which we have seen and heard." }
    ],
    takeaway:"There is salvation in no other name than Jesus Christ, and servants of God must speak what they have seen and heard.",
    quiz:[
      { q:"About how many men had believed by the time Peter and John were arrested?", choices:["About three thousand","About five thousand","About one hundred twenty","About five hundred"], a:1, why:"Acts 4:4 says many who heard the word believed, and the number of the men was about five thousand." },
      { q:"What did the council perceive about Peter and John's boldness?", choices:["They had trained under Gamaliel","They were Roman citizens","They were unlearned and ignorant men who had been with Jesus","They spoke by the power of the temple priests"], a:2, why:"The rulers marvelled at their boldness, took knowledge that they had been with Jesus, and could say nothing against the healed man standing with them." },
      { q:"What did the believers pray for after Peter and John reported the council's threats?", choices:["That God would punish the council immediately","That they could move to another city","That the healed man would testify also","That with all boldness they might speak God's word while He stretched forth His hand to heal"], a:3, why:"Their prayer asked the Lord to behold the threatenings and grant boldness to speak, with signs and wonders done by the name of Jesus." }
    ] },
  { n:5, summary:"A believing couple, Ananias and Sapphira, sell a possession and secretly keep back part of the price while pretending to give it all. Peter confronts the lie: they have not lied to men but to God, and husband and wife each fall down dead, so that great fear comes on the church. Signs and wonders multiply through the apostles, and the sick are brought from surrounding cities and healed every one. The high priest, of the sect of the Sadducees, jails the apostles, but an angel opens the prison at night and sends them back to teach in the temple. Hauled before the council again, Peter and the apostles answer that they ought to obey God rather than men. When the council wants to kill them, the respected Pharisee Gamaliel counsels restraint: works of men come to nought, but if this work is of God, it cannot be overthrown. The apostles are beaten, released, and go rejoicing to suffer for His name, teaching daily.",
    context:"Peter and the apostles answer the council in Jerusalem after an angel frees them from the common prison, in the early days of the church there.",
    keyVerses:[
      { ref:"Acts 5:3", text:"But Peter said, Ananias, why hath Satan filled thine heart to lie to the Holy Ghost, and to keep back part of the price of the land?" },
      { ref:"Acts 5:29", text:"Then Peter and the other apostles answered and said, We ought to obey God rather than men." },
      { ref:"Acts 5:39", text:"But if it be of God, ye cannot overthrow it; lest haply ye be found even to fight against God." }
    ],
    takeaway:"We ought to obey God rather than men, and no lie before Him is worth the price; His work cannot be overthrown.",
    quiz:[
      { q:"What did Ananias and Sapphira do with the price of the possession they sold?", choices:["Kept back part of the price while pretending to bring all","Gave all of it to the apostles","Refused to sell the land","Borrowed more money before giving"], a:0, why:"They kept back part of the price, his wife also being privy to it, yet pretended they had given the whole amount." },
      { q:"Who counseled the council to leave the apostles alone, and on what reasoning?", choices:["Nicodemus, citing a fair-trial rule","Gamaliel, saying if the work be of men it will come to nought, but if of God it cannot be overthrown","Pilate, claiming Roman jurisdiction","The captain of the temple, fearing the people"], a:1, why:"Gamaliel, a Pharisee doctor of the law had in reputation among all the people, cited Theudas and Judas of Galilee and warned against fighting against God." },
      { q:"How did the apostles respond after being beaten and commanded not to speak in the name of Jesus?", choices:["They hid in Jerusalem for a season","They complained to the Roman authorities","They departed rejoicing that they were counted worthy to suffer shame for his name, and taught daily","They moved their headquarters to Antioch"], a:2, why:"Acts 5:41-42 says they rejoiced to suffer shame for his name and ceased not daily in the temple and every house to teach and preach Jesus Christ." }
    ] },
  { n:6, summary:"As the disciples multiply, a complaint arises that Grecian widows are neglected in the daily ministration. The twelve gather the believers and propose that the congregation choose seven men of honest report, full of the Holy Ghost and wisdom, to manage the service, while the apostles devote themselves continually to prayer and the ministry of the word. The choice falls on Stephen, Philip, Prochorus, Nicanor, Timon, Parmenas, and Nicolas; the apostles pray and lay hands on them, and the word of God spreads so that many priests become obedient to the faith. Stephen, full of faith and power, works great wonders, but members of several synagogues cannot withstand his wisdom and suborn men to accuse him of blasphemy against Moses, God, the holy place, and the law. Brought before the council under false witness, Stephen's face shines like the face of an angel.",
    context:"The twelve appoint seven servants over the daily ministration in Jerusalem as the church grows, and Stephen is seized and brought before the council.",
    keyVerses:[
      { ref:"Acts 6:3", text:"Wherefore, brethren, look ye out among you seven men of honest report, full of the Holy Ghost and wisdom, whom we may appoint over this business." },
      { ref:"Acts 6:4", text:"But we will give ourselves continually to prayer, and to the ministry of the word." },
      { ref:"Acts 6:15", text:"And all that sat in the council, looking steadfastly on him, saw his face as it had been the face of an angel." }
    ],
    takeaway:"Faithful, Spirit-filled servants are set apart so that prayer and the ministry of the word continue as the Church grows.",
    quiz:[
      { q:"Who was named first among the seven men chosen over the daily ministration?", choices:["Stephen","Philip","Prochorus","Nicolas"], a:0, why:"The multitude chose Stephen, a man full of faith and of the Holy Ghost, and Philip, and Prochorus, and Nicanor, and Timon, and Parmenas, and Nicolas." },
      { q:"Why did the twelve have the congregation choose seven men over this business?", choices:["Because the apostles were ill","So the apostles could continue in prayer and the ministry of the word without serving tables","Because the Roman governor ordered it","Because the widows demanded new leaders"], a:1, why:"The twelve said it was not reason that they should leave the word of God and serve tables; the seven would be appointed over the business." },
      { q:"What did all who sat in the council see when they looked at Stephen?", choices:["A man trembling with fear","Signs of illness and weakness","A proud and angry expression","His face as it had been the face of an angel"], a:3, why:"Acts 6:15 says all that sat in the council saw his face as it had been the face of an angel." }
    ] },
  { n:7, summary:"Summoned before the high priest, Stephen answers with Israel's whole story. God called Abraham out of Mesopotamia, promised him a land and a covenant, preserved Joseph through betrayal into Egypt, and raised up Moses, first refused by his brethren and later sent as ruler and deliverer, to bring Israel out after wonders in Egypt and the Red Sea. Yet the fathers refused Moses, made the golden calf, and turned to idolatry, though they had the tabernacle of witness, and Solomon later built the temple. Stephen declares that the most High dwells not in temples made with hands, and charges the council with resisting the Holy Ghost as their fathers persecuted the prophets, betraying and murdering the Just One. Enraged, they stone him outside the city while Stephen, full of the Holy Ghost, sees the Son of man standing at God's right hand and dies praying that the Lord receive his spirit and not lay this sin to their charge.",
    context:"Stephen answers the high priest before the council in Jerusalem with a speech on Israel's history, and is stoned outside the city.",
    keyVerses:[
      { ref:"Acts 7:51", text:"Ye stiffnecked and uncircumcised in heart and ears, ye do always resist the Holy Ghost: as your fathers did, so do ye." },
      { ref:"Acts 7:55", text:"But he, being full of the Holy Ghost, looked up steadfastly into heaven, and saw the glory of God, and Jesus standing on the right hand of God," },
      { ref:"Acts 7:59", text:"And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit." }
    ],
    takeaway:"The Spirit makes witnesses bold enough to testify of Christ even when it costs everything, and to forgive as they die.",
    quiz:[
      { q:"At whose feet did the witnesses lay their clothes while they stoned Stephen?", choices:["A young man named Saul","Peter","Gamaliel","Philip"], a:0, why:"Acts 7:58 says the witnesses laid down their clothes at a young man's feet, whose name was Saul." },
      { q:"What charge did Stephen make against the council just before his vision of the heavens opened?", choices:["They had disobeyed the dietary law","They had failed to pay the temple tax","They were stiffnecked, always resisting the Holy Ghost as their fathers persecuted the prophets","They had forsaken the synagogue on the sabbath"], a:2, why:"He called them stiffnecked and uncircumcised in heart and ears, betrayers and murderers of the Just One who had not kept the law they received." },
      { q:"What did Stephen pray as he was being stoned?", choices:["That God would send fire on his killers","That he might escape the city","That Rome would defend him","Lord, lay not this sin to their charge"], a:3, why:"He knelt and cried with a loud voice, Lord, lay not this sin to their charge, and when he had said this he fell asleep." }
    ] },
  { n:8, summary:"Stephen's death opens a season of persecution: Saul ravages the church, dragging believers to prison, and the scattered saints carry the gospel through Judea and Samaria. Philip preaches Christ in Samaria with miracles and great joy, and many are baptized, including the sorcerer Simon. When Peter and John come from Jerusalem, the Samaritans receive the Holy Ghost by the laying on of hands, and Simon offers money for that power. Peter rebukes him: the gift of God cannot be purchased with money, though he urges Simon to repent. Then an angel sends Philip toward Gaza, where he meets an Ethiopian officer of Queen Candace reading Isaiah's prophecy of a lamb led to slaughter. Philip preaches Jesus from that scripture, and when they come to water the eunuch confesses faith that Jesus Christ is the Son of God and is baptized. The Spirit carries Philip away to Azotus, and he preaches on to Caesarea.",
    context:"Under the persecution that followed Stephen's death, Philip preaches in Samaria and to an Ethiopian official on the desert road from Jerusalem to Gaza.",
    keyVerses:[
      { ref:"Acts 8:4", text:"Therefore they that were scattered abroad went every where preaching the word." },
      { ref:"Acts 8:20", text:"But Peter said unto him, Thy money perish with thee, because thou hast thought that the gift of God may be purchased with money." },
      { ref:"Acts 8:37", text:"And Philip said, If thou believest with all thine heart, thou mayest. And he answered and said, I believe that Jesus Christ is the Son of God." }
    ],
    takeaway:"Persecution cannot stop the gospel; it scatters witnesses everywhere, and God's gifts cannot be bought with money.",
    quiz:[
      { q:"Which Samaritan sorcerer offered money for the power to give the Holy Ghost?", choices:["Bar-jesus","Simon","Elymas","Sceva"], a:1, why:"Simon, who had long bewitched the people of Samaria with sorceries, offered the apostles money after seeing the Spirit given by laying on of hands." },
      { q:"What scripture was the Ethiopian eunuch reading when Philip joined his chariot?", choices:["The Psalms of David","The law of Moses","A passage from Esaias the prophet about a lamb led to slaughter","The book of the twelve prophets"], a:2, why:"He was reading Esaias, the passage about a sheep led to the slaughter, and Philip began at the same scripture and preached unto him Jesus." },
      { q:"What positive result came from the persecution that began with Stephen's death?", choices:["The apostles were finally left in peace","The Romans outlawed mob violence","The Jerusalem church became wealthier","The scattered believers went everywhere preaching the word"], a:3, why:"Those scattered abroad by the persecution travelled through Judea and Samaria preaching, and Philip carried the gospel to Samaria and the Ethiopian official." }
    ] },
  { n:9, summary:"Saul, armed with letters for Damascus, still breathes threatenings against the disciples when a light from heaven stops him on the road. The voice of the risen Lord asks why he persecutes Him, and the blinded Saul is led into the city, where he fasts three days. The Lord sends a disciple named Ananias, who lays hands on Saul so he receives sight and the Holy Ghost, and Saul is baptized. He immediately preaches Christ in the synagogues, proving that Jesus is the very Christ, and when the Jews plot his death the disciples lower him over the wall in a basket. In Jerusalem the fearful believers distrust him until Barnabas vouches for his conversion; after further preaching and danger the brethren send him to Tarsus, and the churches have rest and multiply. Peter then heals Aeneas of palsy at Lydda and raises Tabitha, also called Dorcas, at Joppa, and many believe.",
    context:"Saul is converted near Damascus and preaches there and in Jerusalem; later Peter heals in Lydda and raises Dorcas in Joppa.",
    keyVerses:[
      { ref:"Acts 9:4", text:"And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?" },
      { ref:"Acts 9:15", text:"But the Lord said unto him, Go thy way: for he is a chosen vessel unto me, to bear my name before the Gentiles, and kings, and the children of Israel:" },
      { ref:"Acts 9:20", text:"And straightway he preached Christ in the synagogues, that he is the Son of God." }
    ],
    takeaway:"The Lord can turn a persecutor into a chosen vessel; conversion leads to baptism, then to witnessing of Jesus Christ.",
    quiz:[
      { q:"What city was Saul traveling to when the light from heaven shone around him?", choices:["Damascus","Tarsus","Antioch","Joppa"], a:0, why:"Saul went to the high priest for letters to Damascus to the synagogues, and as he journeyed he came near Damascus when the light shone." },
      { q:"Who brought Saul to the apostles in Jerusalem when the disciples were afraid of him?", choices:["Ananias of Damascus","Barnabas","Peter","Philip the evangelist"], a:1, why:"Barnabas took him and declared to the apostles how Saul had seen the Lord in the way and preached boldly at Damascus." },
      { q:"What did Saul do immediately after receiving sight and being baptized?", choices:["He returned to persecuting the church","He retired to Tarsus in silence","He preached Christ in the synagogues, that he is the Son of God","He waited years for further instruction"], a:2, why:"Straightway Saul preached Christ in the synagogues and confounded the Jews at Damascus, proving that this is very Christ." }
    ] },
  { n:10, summary:"Cornelius, a devout Roman centurion in Caesarea, sees an angel who tells him his prayers and alms are remembered before God and sends him to fetch Peter from Joppa. The next day Peter, praying on a housetop, falls into a trance and three times sees a sheet of animals lowered from heaven with the command to kill and eat, learning that what God has cleansed he must not call common. Led by the Spirit, Peter goes to Caesarea, where Cornelius has gathered his kinsmen and friends. Peter confesses that God is no respecter of persons, that in every nation those who fear Him and work righteousness are accepted, and preaches peace by Jesus Christ, who was slain, raised the third day, and ordained Judge of quick and dead. While Peter is still speaking, the Holy Ghost falls on the Gentiles, who speak with tongues and magnify God, and Peter commands that they be baptized in the name of the Lord.",
    context:"In Caesarea, the Roman centurion Cornelius and Peter receive visions that bring them together, and the Holy Ghost falls on Cornelius's household.",
    keyVerses:[
      { ref:"Acts 10:34", text:"Then Peter opened his mouth, and said, Of a truth I perceive that God is no respecter of persons:" },
      { ref:"Acts 10:43", text:"To him give all the prophets witness, that through his name whosoever believeth in him shall receive remission of sins." },
      { ref:"Acts 10:47", text:"Can any man forbid water, that these should not be baptized, which have received the Holy Ghost as well as we?" }
    ],
    takeaway:"God is no respecter of persons: in every nation, those who fear Him and work righteousness are accepted with Him.",
    quiz:[
      { q:"What was Cornelius's position in the Roman army?", choices:["A centurion of the band called the Italian band","Captain of the temple guard","A governor of Judea","A commander of chariots"], a:0, why:"Acts 10:1 introduces Cornelius as a centurion of the band called the Italian band, living in Caesarea." },
      { q:"What lesson did Peter's vision of the sheet three times teach him?", choices:["That clean animals were healthier to eat","That what God hath cleansed, none should call common, preparing him to preach to Gentiles","That he should fast three days","That Caesarea would soon be destroyed"], a:1, why:"The voice said, What God hath cleansed, that call not thou common, and Peter later told Cornelius that God had showed him not to call any man common or unclean." },
      { q:"What happened while Peter was still preaching to Cornelius's household?", choices:["The house was shaken by an earthquake","Cornelius was ordained an apostle","An angel appeared visibly to everyone","The Holy Ghost fell on all who heard the word, and they spoke with tongues and magnified God"], a:3, why:"The Jewish believers were astonished that on the Gentiles also was poured out the gift of the Holy Ghost, so Peter commanded that they be baptized." }
    ] },
  { n:11, summary:"When Peter returns to Jerusalem, believers of the circumcision criticize him for eating with uncircumcised men. He rehearses the whole sequence: his trance in Joppa, the voice from heaven, the Spirit's command to go with the messengers without doubting, and the Holy Ghost falling on Cornelius's household as on the apostles at the beginning. Confronted with the question, what was I, that I could withstand God, his critics hold their peace and glorify God for granting the Gentiles repentance unto life. Meanwhile believers scattered by the persecution after Stephen preach as far as Phoenicia, Cyprus, and Antioch, where men of Cyprus and Cyrene speak to the Grecians and a great number believe. The church in Jerusalem sends Barnabas, who rejoices, exhorts the converts to cleave to the Lord, and fetches Saul from Tarsus; together they teach a whole year in Antioch, where the disciples are first called Christians. The prophet Agabus foretells a famine, and the disciples send relief to Judea by Barnabas and Saul.",
    context:"Peter defends his visit to Cornelius before the church at Jerusalem, and Barnabas brings Saul from Tarsus to teach at Antioch, where believers are first called Christians.",
    keyVerses:[
      { ref:"Acts 11:17", text:"Forasmuch then as God gave them the like gift as he did unto us, who believed on the Lord Jesus Christ; what was I, that I could withstand God?" },
      { ref:"Acts 11:18", text:"When they heard these things, they held their peace, and glorified God, saying, Then hath God also to the Gentiles granted repentance unto life." },
      { ref:"Acts 11:26", text:"And when he had found him, he brought him unto Antioch. And it came to pass, that a whole year they assembled themselves with the church, and taught much people. And the disciples were called Christians first in Antioch." }
    ],
    takeaway:"When God gives the like gift of the Spirit to any who believe, no one can withstand Him; the answer is repentance unto life for all.",
    quiz:[
      { q:"In what city were the disciples first called Christians?", choices:["Antioch","Jerusalem","Tarsus","Cyprus"], a:0, why:"Barnabas brought Saul to Antioch, where they taught the church a whole year, and the disciples were called Christians first in Antioch." },
      { q:"What settled the criticism that Peter had eaten with uncircumcised men?", choices:["A vote of the whole church","A letter from Cornelius","Peter's account of the vision and God giving the Gentiles the like gift of the Holy Ghost","A command from the Roman authorities"], a:2, why:"Peter rehearsed the matter from the beginning; when the critics heard it they held their peace and glorified God, saying God had granted the Gentiles repentance unto life." },
      { q:"How did the Antioch disciples respond to Agabus's prophecy of a great dearth?", choices:["They stored food inside the temple","They moved to Jerusalem for safety","They dismissed the prophecy as false","They determined to send relief to the brethren in Judea, every man according to his ability"], a:3, why:"Acts 11:29-30 says every disciple gave according to his ability, and the relief was carried to the elders by Barnabas and Saul." }
    ] },
  { n:12, summary:"King Herod begins to trouble the church, killing James the brother of John with the sword and imprisoning Peter during the days of unleavened bread, guarded by four quaternions of soldiers. The church prays without ceasing, and on the night before Herod intends to bring Peter forth, an angel wakes him, his chains fall off, the iron gate opens of its own accord, and Peter finds himself free in the street. He goes to Mary's house, where the praying saints can hardly believe Rhoda's report that Peter stands at the gate. After telling of his deliverance and sending word to James and the brethren, Peter departs, and the keepers are put to death. At Caesarea, Herod accepts the crowd's flattery that he speaks as a god, fails to give God the glory, and is struck by an angel and dies, while the word of God grows and multiplies. Barnabas and Saul return to Antioch with John Mark.",
    context:"King Herod persecutes the church in Jerusalem, killing James and imprisoning Peter, and later dies at Caesarea for not giving God the glory.",
    keyVerses:[
      { ref:"Acts 12:5", text:"Peter therefore was kept in prison: but prayer was made without ceasing of the church unto God for him." },
      { ref:"Acts 12:7", text:"And, behold, the angel of the Lord came upon him, and a light shined in the prison: and he smote Peter on the side, and raised him up, saying, Arise up quickly. And his chains fell off from his hands." },
      { ref:"Acts 12:23", text:"And immediately the angel of the Lord smote him, because he gave not God the glory: and he was eaten of worms, and gave up the ghost." }
    ],
    takeaway:"Constant prayer releases God's power to deliver, but glory belongs to God alone; the word of God grows and multiplies.",
    quiz:[
      { q:"Which apostle did Herod kill with the sword?", choices:["Peter","James the brother of John","Andrew","Philip"], a:1, why:"Acts 12:2 says Herod killed James the brother of John with the sword, and because it pleased the Jews he proceeded to take Peter also." },
      { q:"What happened when Peter knocked at the gate of Mary's house?", choices:["The guards seized him at the door","Rhoda let him in immediately","Rhoda knew his voice but did not open the gate; the saints called her mad, then saw him and were astonished","The household fled out a back door"], a:2, why:"Rhoda ran in and told how Peter stood before the gate; they said thou art mad or it is his angel, but Peter continued knocking and they saw him and were astonished." },
      { q:"What contrast does the chapter draw at its close?", choices:["Herod's dynasty grew while the church scattered","Peter remained in prison while James was freed","The soldiers were rewarded and Herod traveled to Rome","Herod died for not giving God the glory, while the word of God grew and multiplied"], a:3, why:"The angel smote Herod because he gave not God the glory, but the word of God grew and multiplied, and Barnabas and Saul returned with John Mark." }
    ] },
  { n:13, summary:"While the prophets and teachers of Antioch minister and fast, the Holy Ghost says, Separate me Barnabas and Saul; after prayer and fasting with laid-on hands, they sail to Cyprus. At Paphos the deputy Sergius Paulus wants to hear the word of God, but the sorcerer Elymas tries to turn him aside until Saul, who is also called Paul, rebukes him with blindness for a season, and the astonished deputy believes. At Antioch in Pisidia Paul is invited to speak in the synagogue and traces Israel's history from Egypt through David to Jesus, the promised Saviour whom the Jerusalem rulers condemned but God raised from the dead. Through Him, he says, forgiveness of sins is preached and believers are justified from what the law of Moses could not justify. Almost the whole city gathers the next sabbath; when the Jews contradict and blaspheme, Paul and Barnabas declare they will turn to the Gentiles, who are glad and believe. Persecution expels the missionaries, who shake off the dust of their feet and press on to Iconium.",
    context:"From Antioch, Barnabas and Saul are sent out by the Holy Ghost to Cyprus and then to the synagogue of Antioch in Pisidia on the first missionary journey.",
    keyVerses:[
      { ref:"Acts 13:2", text:"As they ministered to the Lord, and fasted, the Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them." },
      { ref:"Acts 13:38", text:"Be it known unto you therefore, men and brethren, that through this man is preached unto you the forgiveness of sins:" },
      { ref:"Acts 13:46", text:"Then Paul and Barnabas waxed bold, and said, It was necessary that the word of God should first have been spoken to you: but seeing ye put it from you, and judge yourselves unworthy of everlasting life, lo, we turn to the Gentiles." }
    ],
    takeaway:"The Holy Ghost calls and sets apart servants for the work; through Jesus comes forgiveness and justification the law could not give.",
    quiz:[
      { q:"Which Roman deputy of Cyprus heard Paul and Barnabas and believed?", choices:["Sergius Paulus","Felix","Gallio","Publius"], a:0, why:"Sergius Paulus, the deputy of the country, a prudent man, desired to hear the word of God and believed, astonished at the doctrine of the Lord." },
      { q:"In his Pisidian Antioch sermon, what did Paul say believers receive through Jesus?", choices:["Circumcision of the flesh","Forgiveness of sins and justification from all things the law of Moses could not justify","Land in the region of Galatia","Freedom from Roman taxation"], a:1, why:"Paul declared that through this man is preached the forgiveness of sins, and by him all that believe are justified from all things." },
      { q:"How did Paul and Barnabas respond when they were expelled from Antioch in Pisidia?", choices:["They returned to Jerusalem to complain","They renounced their mission","They shook off the dust of their feet against them and came unto Iconium","They hid in Paphos until the danger passed"], a:2, why:"Paul and Barnabas shook off the dust of their feet against them and came unto Iconium, and the disciples were filled with joy and with the Holy Ghost." }
    ] },
  { n:14, summary:"In Iconium they preach so that a great multitude of Jews and Greeks believe, but the city divides and a plot to stone them drives them on to Lystra and Derbe. At Lystra Paul heals a man crippled from birth, and the crowds conclude the gods have come down, calling Barnabas Jupiter and Paul Mercurius. The priest of Jupiter prepares sacrifice until the two apostles tear their clothes and protest that they are men of like passions, preaching the living God who made heaven and earth and leaves the nations witness of Himself in rain, fruitful seasons, food, and gladness. Jews from Antioch and Iconium then persuade the people, who stone Paul and drag him out of the city supposing him dead; he rises, returns to the city, and the next day goes with Barnabas to Derbe. Returning through Lystra, Iconium, and Pisidian Antioch, they confirm the disciples, ordain elders in every church, and report at Antioch in Syria how God had opened the door of faith unto the Gentiles.",
    context:"On the first missionary journey, Paul and Barnabas preach in Iconium, Lystra, and Derbe, then return through Pisidia and Pamphylia to report at Antioch in Syria.",
    keyVerses:[
      { ref:"Acts 14:15", text:"And saying, Sirs, why do ye these things? We also are men of like passions with you, and preach unto you that ye should turn from these vanities unto the living God, which made heaven, and earth, and the sea, and all things that are therein:" },
      { ref:"Acts 14:22", text:"Confirming the souls of the disciples, and exhorting them to continue in the faith, and that we must through much tribulation enter into the kingdom of God." },
      { ref:"Acts 14:27", text:"And when they were come, and had gathered the church together, they rehearsed all that God had done with them, and how he had opened the door of faith unto the Gentiles." }
    ],
    takeaway:"Servants of God are men of like passions; through much tribulation the saints enter the kingdom of God.",
    quiz:[
      { q:"Whom did the people of Lystra call Mercurius?", choices:["Paul, because he was the chief speaker","Barnabas, because he was older","Their own priest of Jupiter","A visitor from Derbe"], a:0, why:"The Lystrians called Barnabas Jupiter and Paul Mercurius, because he was the chief speaker of the two." },
      { q:"What happened to Paul at Lystra after Jews from Antioch and Iconium persuaded the people?", choices:["He was jailed by the town clerk","He was stoned and drawn out of the city as dead, but rose up and returned to the city","He was worshipped as a god","He sailed home from Attalia in defeat"], a:1, why:"The people stoned Paul and drew him out of the city supposing he had been dead; as the disciples stood round about him he rose up and came into the city." },
      { q:"What did Paul and Barnabas teach the disciples as they revisited each city?", choices:["That faith removes all tribulation","That Gentiles must be circumcised","That elders should never be ordained","That we must through much tribulation enter into the kingdom of God"], a:3, why:"They confirmed the souls of the disciples, exhorting them to continue in the faith despite tribulation, and ordained elders in every church with prayer and fasting." }
    ] },
  { n:15, summary:"Men from Judea teach Antioch's believers that circumcision after the manner of Moses is necessary to salvation, touching off a dispute that sends Paul and Barnabas to Jerusalem to consult the apostles and elders. After much arguing, Peter recalls how God chose him to bring the gospel to Cornelius's household, gave the Gentiles the Holy Ghost, and put no difference between Jew and Gentile, purifying hearts by faith; why then put on the disciples' necks a yoke neither fathers nor children could bear? Barnabas and Paul report the miracles among the Gentiles, and James proposes that they not trouble those turned to God, writing only that they abstain from idol pollutions, fornication, things strangled, and blood. The council's letter, carried by Judas Barsabas and Silas, pleases Antioch, which rejoices for the consolation. Later Paul and Barnabas split over taking John Mark: Barnabas takes Mark to Cyprus, while Paul chooses Silas and confirms the churches through Syria and Cilicia.",
    context:"At Jerusalem, the apostles and elders gather with Paul and Barnabas to decide whether Gentile converts must keep the law of Moses, then write their decision to Antioch.",
    keyVerses:[
      { ref:"Acts 15:8", text:"And God, which knoweth the hearts, bare them witness, giving them the Holy Ghost, even as he did unto us;" },
      { ref:"Acts 15:11", text:"But we believe that through the grace of the Lord Jesus Christ we shall be saved, even as they." },
      { ref:"Acts 15:28", text:"For it seemed good to the Holy Ghost, and to us, to lay upon you no greater burden than these necessary things;" }
    ],
    takeaway:"God purifies hearts by faith, and through the grace of the Lord Jesus Christ all are saved; councils should not add burdens He has not laid.",
    quiz:[
      { q:"What teaching from men out of Judæa started the dispute settled in this chapter?", choices:["Except ye be circumcised after the manner of Moses, ye cannot be saved","The Sabbath must be moved to another day","Jewish Christians must give up the temple","Gentiles must not read the scriptures"], a:0, why:"Certain men taught the brethren at Antioch that circumcision after the manner of Moses was required for salvation, leading to the council in Jerusalem." },
      { q:"What evidence did Peter remind the council of from the conversion of Cornelius's household?", choices:["That they had paid tithes faithfully","That they had studied under Gamaliel","That God gave the Gentiles the Holy Ghost, purifying their hearts by faith","That they had already kept the whole law"], a:2, why:"Peter argued that God bare the Gentiles witness by giving them the Holy Ghost even as he did unto the Jews, so no yoke should be laid on their necks." },
      { q:"Why did Paul and Barnabas separate before the second journey?", choices:["They disagreed about the council's letter","Barnabas wished to settle in Tarsus","Paul considered Barnabas unconverted","They contended sharply over taking John Mark, so Barnabas took Mark to Cyprus while Paul chose Silas"], a:3, why:"Paul thought Mark, who had departed from them in Pamphylia, should not come; Barnabas took Mark and sailed to Cyprus, and Paul went through Syria and Cilicia with Silas." }
    ] },
  { n:16, summary:"Paul takes Timothy and circumcises him because of the Jews in those quarters. Forbidden by the Holy Ghost to preach in Asia or Bithynia, they come to Troas, where Paul's vision of a man pleading, Come over into Macedonia, and help us, brings the gospel to Philippi. There the Lord opens the heart of Lydia, a seller of purple, who is baptized with her household and hosts the missionaries. When Paul casts a divining spirit out of a fortune-telling damsel, her angry masters drag Paul and Silas before the magistrates, who beat them and thrust them into the inner prison. At midnight they pray and sing praises until an earthquake opens every door; the jailor, about to kill himself, is stopped by Paul and asks what he must do to be saved. Believing on the Lord Jesus Christ, he and all his house are baptized the same hour. Learning the prisoners are Romans, the magistrates ask them to leave; the missionaries comfort the brethren at Lydia's house and go on their way.",
    context:"Called by a vision from Troas into Macedonia, Paul and Silas preach at Philippi, where Lydia believes and a jailor and his household are baptized after an earthquake.",
    keyVerses:[
      { ref:"Acts 16:9", text:"And a vision appeared to Paul in the night; There stood a man of Macedonia, and prayed him, saying, Come over into Macedonia, and help us." },
      { ref:"Acts 16:25", text:"And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them." },
      { ref:"Acts 16:31", text:"And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house." }
    ],
    takeaway:"The Spirit directs the work across borders; praise in tribulation opens hearts, and belief on the Lord Jesus Christ saves.",
    quiz:[
      { q:"What was Lydia's trade?", choices:["Tentmaking","Selling purple cloth","Fishing","Silver-smithing"], a:1, why:"Lydia was a seller of purple from the city of Thyatira, whose heart the Lord opened as she heard Paul at the riverside." },
      { q:"Why were Paul and Silas beaten and imprisoned in Philippi?", choices:["They robbed the marketplace","They insulted the magistrates","Paul cast a spirit of divination out of a damsel, destroying her masters' gain from her soothsaying","They refused to pay taxes to Rome"], a:2, why:"When her masters saw the hope of their gains was gone, they caught Paul and Silas and accused them of troubling the city before the magistrates." },
      { q:"What answer did Paul and Silas give the trembling jailor who asked what he must do to be saved?", choices:["Keep the law of Moses perfectly","Pay the prisoners for their stripes","Escape the city before daylight","Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house"], a:3, why:"They spoke the word of the Lord to him and all in his house, and the same hour of the night he was baptized with all his." }
    ] },
  { n:17, summary:"Paul reasons three sabbaths in the Thessalonica synagogue, showing from the scriptures that Christ must suffer and rise, and some Jews, many devout Greeks, and chief women believe; but an uproar led by unbelieving Jews forces the missionaries to Berea by night. The Bereans are more noble, receiving the word readily and searching the scriptures daily to see whether these things are so, and many believe until Thessalonian agitators follow. Sent on to Athens, Paul finds the city wholly given to idolatry and disputes daily in the synagogue and market until philosophers bring him to Areopagus. There he declares the altar inscribed to the unknown God: the Creator dwells not in temples made with hands, gives all life and breath, has made of one blood all nations, and now commands every where to repent, having appointed a day of judgment by the man He raised from the dead. Some mock the resurrection; others, including Dionysius and Damaris, believe.",
    context:"Paul preaches in the synagogues of Thessalonica and Berea and then at Athens before the Areopagus on Mars' hill, waiting there for Silas and Timotheus.",
    keyVerses:[
      { ref:"Acts 17:11", text:"These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so." },
      { ref:"Acts 17:23", text:"For as I passed by, and beheld your devotions, I found an altar with this inscription, TO THE UNKNOWN GOD. Whom therefore ye ignorantly worship, him declare I unto you." },
      { ref:"Acts 17:30", text:"And the times of this ignorance God winked at; but now commandeth all men every where to repent:" }
    ],
    takeaway:"Search the scriptures daily to test what you hear; God is not far from any of us and now commands all men everywhere to repent.",
    quiz:[
      { q:"Which city's Jews were called more noble because they searched the scriptures daily?", choices:["Berea","Thessalonica","Athens","Corinth"], a:0, why:"The Bereans received the word with all readiness of mind and searched the scriptures daily whether those things were so, and many believed." },
      { q:"How did Paul open his sermon on Mars' hill?", choices:["By condemning Caesar's decrees","By pointing to their altar inscribed TO THE UNKNOWN GOD and declaring Him","By reading the law of Moses aloud","By performing a healing in the market"], a:1, why:"Paul told the Athenians he had found an altar to the unknown God and that Him whom they ignorantly worship he declared unto them." },
      { q:"How did the Athenians respond to Paul's preaching of the resurrection?", choices:["The whole city believed at once","Paul was arrested and beaten","Some mocked, some deferred, and certain believed, including Dionysius and Damaris","The philosophers burned his writings"], a:2, why:"When they heard of the resurrection of the dead, some mocked and others said they would hear him again, yet Dionysius the Areopagite and Damaris clave unto him and believed." }
    ] },
  { n:18, summary:"In Corinth Paul lives and works as a tentmaker with Aquila and Priscilla, Jews recently expelled from Rome by Claudius, and reasons in the synagogue every sabbath. When opposition turns to blasphemy he shakes his raiment and turns to the Gentiles; the synagogue ruler Crispus believes, and the Lord encourages Paul in a night vision, promising no one will hurt him because He has much people in the city. Paul stays a year and six months, and when the Jews accuse him before the deputy Gallio, the governor dismisses the case as a matter of their own law. Sailing for Syria with Aquila and Priscilla, Paul cuts his hair at Cenchrea in fulfillment of a vow, reasons briefly at Ephesus, and travels home by way of Caesarea and Antioch before strengthening the churches of Galatia and Phrygia. At Ephesus the eloquent Apollos, knowing only the baptism of John, is taught the way of God more perfectly by Aquila and Priscilla, then powerfully proves from the scriptures in Achaia that Jesus was Christ.",
    context:"Paul labors as a tentmaker in Corinth for a year and six months under the deputy Gallio, then returns toward Antioch as Apollos arrives at Ephesus.",
    keyVerses:[
      { ref:"Acts 18:9", text:"Then spake the Lord to Paul in the night by a vision, Be not afraid, but speak, and hold not thy peace:" },
      { ref:"Acts 18:10", text:"For I am with thee, and no man shall set on thee to hurt thee: for I have much people in this city." },
      { ref:"Acts 18:26", text:"And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly." }
    ],
    takeaway:"The Lord stands with His servants in long labors, and humble Saints help each other learn the way of God more perfectly.",
    quiz:[
      { q:"With whom did Paul work as a tentmaker in Corinth?", choices:["Aquila and his wife Priscilla","Lydia and her household","Jason and the brethren","Apollos and Sosthenes"], a:0, why:"Paul found Aquila, born in Pontus, with his wife Priscilla, and because he was of the same craft he abode with them and wrought, for they were tentmakers." },
      { q:"What did the Lord promise Paul in the night vision at Corinth?", choices:["That he would rule the church there","That no man would set on him to hurt him, for the Lord had much people in the city","That Corinth would escape all judgment","That he would soon return to Jerusalem wealthy"], a:1, why:"The Lord said, Be not afraid, but speak; I am with thee, and no man shall set on thee to hurt thee, so Paul stayed a year and six months." },
      { q:"What did Paul do when the Jews in Corinth opposed themselves and blasphemed?", choices:["He gave up preaching altogether","He appealed to Gallio before the synagogue meeting","He remained silent for eighteen months","He shook his raiment and said their blood was on their own heads; from then on he would go unto the Gentiles"], a:3, why:"Paul testified that Jesus was Christ, and when they opposed he shook his raiment, declaring himself clean and turning to the Gentiles." }
    ] },
  { n:19, summary:"At Ephesus Paul finds about twelve disciples who know only John's baptism; he baptizes them in the name of the Lord Jesus, lays hands on them, and the Holy Ghost comes on them with tongues and prophecy. After three months in the synagogue he teaches daily for two years in the school of Tyrannus, so that all in Asia hear the word, while God works special miracles and even handkerchiefs from Paul heal the sick. When the seven sons of Sceva try to cast out devils by naming the Jesus whom Paul preaches, the evil spirit overcomes them, and fear makes the name of the Lord Jesus great; new believers burn their books of curious arts worth fifty thousand pieces of silver. Paul resolves to pass through Macedonia and Achaia to Jerusalem and afterward to see Rome. But Demetrius the silversmith stirs the craftsmen, claiming Paul's teaching threatens their trade of silver shrines for Diana, and for two hours the crowded theatre cries, Great is Diana of the Ephesians, until the townclerk quiets them and dismisses the assembly.",
    context:"At Ephesus Paul teaches for two years, first in the synagogue and then in the school of Tyrannus, until a riot over the goddess Diana fills the city theatre.",
    keyVerses:[
      { ref:"Acts 19:2", text:"He said unto them, Have ye received the Holy Ghost since ye believed? And they said unto him, We have not so much as heard whether there be any Holy Ghost." },
      { ref:"Acts 19:15", text:"And the evil spirit answered and said, Jesus I know, and Paul I know; but who are ye?" },
      { ref:"Acts 19:20", text:"So mightily grew the word of God and prevailed." }
    ],
    takeaway:"The word of God grows mightily when believers repent of hidden works; Christ's power belongs to those He authorizes, not to imitators.",
    quiz:[
      { q:"Where did Paul dispute daily after leaving the synagogue at Ephesus?", choices:["The school of one Tyrannus","The theatre by the harbor","The temple of Diana","The judgment seat of the city"], a:0, why:"When divers were hardened and spoke evil of that way, Paul separated the disciples and disputed daily in the school of Tyrannus for two years." },
      { q:"What stirred Demetrius and the craftsmen of Ephesus against Paul?", choices:["Paul owed them payment for shrines","Paul had desecrated Diana's temple","Paul taught that gods made with hands were no gods, endangering their trade of silver shrines for Diana","Paul preached loyalty to Caesar above Diana"], a:2, why:"Demetrius told the workmen their wealth came by this craft and that Paul had turned away many people throughout Asia, threatening both their trade and Diana's worship." },
      { q:"What lesson came from the seven sons of Sceva trying to cast out an evil spirit?", choices:["Exorcism is always successful","The name of Jesus works as a magic formula for anyone","Evil spirits obey all religious men","Authority matters: the evil spirit answered, Jesus I know, and Paul I know; but who are ye?"], a:3, why:"The man with the evil spirit overcame the seven sons of Sceva, and fear fell on all, so that the name of the Lord Jesus was magnified." }
    ] },
  { n:20, summary:"Traveling through Macedonia while Jewish plots redirect his route, Paul sails to Troas, where he preaches so long on the first day of the week that Eutychus, sitting in a window, falls from the third loft and is taken up dead; Paul embraces him, and the young man is brought alive. Passing Miletus, Paul summons the elders of the Ephesian church and reviews his ministry among them: humility, tears, teaching publickly and from house to house, repentance toward God and faith toward Jesus Christ. Bound in spirit for Jerusalem though bonds and afflictions await, he counts his life dear only so that he may finish his course with joy and testify the gospel of the grace of God. He charges the elders to take heed to the flock the Holy Ghost made them overseers of, warns that grievous wolves and perverse men will attack it, commends them to the word of His grace, and reminds them it is more blessed to give than to receive. They weep, embrace him, and accompany him to the ship.",
    context:"Sailing from Macedonia toward Jerusalem for Pentecost, Paul summons the elders of the Ephesian church to meet him at Miletus and gives them a farewell charge.",
    keyVerses:[
      { ref:"Acts 20:24", text:"But none of these things move me, neither count I my life dear unto myself, so that I might finish my course with joy, and the ministry, which I have received of the Lord Jesus, to testify the gospel of the grace of God." },
      { ref:"Acts 20:28", text:"Take heed therefore unto yourselves, and to all the flock, over the which the Holy Ghost hath made you overseers, to feed the church of God, which he hath purchased with his own blood." },
      { ref:"Acts 20:35", text:"I have shewed you all things, how that so labouring ye ought to support the weak, and to remember the words of the Lord Jesus, how he said, It is more blessed to give than to receive." }
    ],
    takeaway:"Finish your course with joy; watch over the flock God purchased, and remember it is more blessed to give than to receive.",
    quiz:[
      { q:"Who fell from the third loft while Paul preached long at Troas?", choices:["Trophimus","Eutychus","Sopater","Tychicus"], a:1, why:"Eutychus, sitting in a window, sank into deep sleep as Paul preached and fell down from the third loft and was taken up dead; Paul restored him." },
      { q:"Why did Paul sail past Ephesus and summon the elders to Miletus?", choices:["The Ephesians had forbidden him to return","He had lost his belongings at Ephesus","He hasted, if it were possible, to be at Jerusalem the day of Pentecost","A plague had broken out in Ephesus"], a:2, why:"Paul determined to sail by Ephesus because he would not spend time in Asia, hasting toward Jerusalem by Pentecost, but he called the elders to him at Miletus." },
      { q:"What warning did Paul give the Ephesian elders about the church's future?", choices:["That all the flock would soon move to Rome","That the church would be exempt from trial","That the elders would all fall away permanently","That grievous wolves would enter in, and men of their own company would draw away disciples"], a:3, why:"Paul warned them to watch, for after his departing wolves would not spare the flock, and perverse men would arise from among themselves." }
    ] },
  { n:21, summary:"Sailing toward Jerusalem, Paul passes through Tyre and stays with Philip the evangelist at Caesarea, where the prophet Agabus binds Paul's girdle on his own hands and feet, foretelling that the Jews will bind its owner and deliver him to the Gentiles. Paul refuses all pleas, declaring himself ready not only to be bound but also to die at Jerusalem for the name of the Lord Jesus, and the company yields, saying, The will of the Lord be done. In Jerusalem Paul reports God's work among the Gentiles to James and the elders, who urge him to join four men under a vow and pay their charges so all may know the rumors are false. Near the end of seven days, Jews from Asia accuse him of teaching against the law and the temple and of bringing Greeks into the temple; the mob drags him out to kill him until soldiers rescue him at the castle stairs, where Paul asks leave to speak to the people.",
    context:"Paul journeys to Jerusalem by way of Tyre and Caesarea, joins a purification rite at James's counsel, and is seized by a mob in the temple and rescued by the chief captain.",
    keyVerses:[
      { ref:"Acts 21:13", text:"Then Paul answered, What mean ye to weep and to break mine heart? for I am ready not to be bound only, but also to die at Jerusalem for the name of the Lord Jesus." },
      { ref:"Acts 21:14", text:"And when he would not be persuaded, we ceased, saying, The will of the Lord be done." },
      { ref:"Acts 21:31", text:"And as they went about to kill him, tidings came unto the chief captain of the band, that all Jerusalem was in an uproar." }
    ],
    takeaway:"Discipleship means counting nothing dearer than the will of the Lord, ready to serve whether it brings honor or bonds.",
    quiz:[
      { q:"Whose house did Paul and his company stay in at Caesarea?", choices:["Philip the evangelist, one of the seven","Simon the tanner","Mnason of Cyprus","Cornelius the centurion"], a:0, why:"The company entered into the house of Philip the evangelist, one of the seven, whose four daughters did prophesy, and abode with him." },
      { q:"What did James and the elders ask Paul to do to answer the rumors against him?", choices:["Leave Jerusalem before Pentecost","Take four men under a vow, purify himself with them, and pay their charges, showing the rumors false","Publicly renounce his mission to the Gentiles","Bring his case before the Roman court"], a:1, why:"Thousands of zealous Jewish believers had been told Paul taught Jews to forsake Moses; the proposed act would show the reports were nothing." },
      { q:"How did Paul answer those who wept and pleaded with him not to go up to Jerusalem?", choices:["He agreed to delay his journey","He promised to avoid the temple","He said he was ready not only to be bound but also to die at Jerusalem for the name of the Lord Jesus","He sent the prophet Agabus in his place"], a:2, why:"Paul asked what they meant by weeping and breaking his heart, and when he would not be persuaded the company ceased, saying, The will of the Lord be done." }
    ] },
  { n:22, summary:"Given leave by the chief captain, Paul quiets the Jerusalem mob by speaking in the Hebrew tongue and recounts his life: educated at the feet of Gamaliel, zealous like his hearers, he persecuted this way unto death and carried letters to Damascus to bind the saints. Near Damascus a great light at noon stopped him, the voice of Jesus of Nazareth asked why he persecuted Him, and a blinded Saul was led into the city, where the devout Ananias restored his sight, told him God had chosen him to know His will and see the Just One, and urged him to arise and be baptized, washing away his sins. Later, praying in the temple, Paul saw the Lord warn him to leave Jerusalem and send him far hence unto the Gentiles; at that word the crowd erupts again. About to be scourged, Paul asks whether it is lawful to scourge an uncondemned Roman, and the alarmed chief captain releases his bands and sets him before the council the next day.",
    context:"Standing on the stairs of the castle in Jerusalem, Paul defends himself in the Hebrew tongue before the angry crowd that had tried to kill him in the temple.",
    keyVerses:[
      { ref:"Acts 22:14", text:"And he said, The God of our fathers hath chosen thee, that thou shouldest know his will, and see that Just One, and shouldest hear the voice of his mouth." },
      { ref:"Acts 22:16", text:"And now why tarriest thou? arise, and be baptized, and wash away thy sins, calling on the name of the Lord." },
      { ref:"Acts 22:21", text:"And he said unto me, Depart: for I will send thee far hence unto the Gentiles." }
    ],
    takeaway:"A personal testimony of what you have seen and heard, kept with baptism and a pure heart, no crowd can silence.",
    quiz:[
      { q:"At whose feet was Paul brought up, taught according to the perfect manner of the law of the fathers?", choices:["Gamaliel","Nicodemus","Stephen","Apollos"], a:0, why:"Paul told the crowd he was born in Tarsus yet brought up in Jerusalem at the feet of Gamaliel, zealous toward God as they were." },
      { q:"What words from Paul's speech made the crowd cry, Away with such a fellow from the earth?", choices:["That he was born in Tarsus","That the Lord would send him far hence unto the Gentiles","That he had studied under Gamaliel","That he had been baptized"], a:1, why:"The mob gave him audience until the word that the Lord would send him to the Gentiles; then they lifted up their voices against him." },
      { q:"How did Paul's Roman citizenship spare him at the castle?", choices:["The soldiers feared his family's influence","He bribed the centurion with temple money","The chief captain owed Caesar a favor","As he was bound for scourging he asked, Is it lawful to scourge a Roman, and uncondemned?"], a:3, why:"When the centurion reported Paul was a Roman, the chief captain, who had bought his citizenship with a great sum, was afraid and loosed Paul's bands." }
    ] },
  { n:23, summary:"Facing the council, Paul protests that he has lived in all good conscience before God, and when the high priest Ananias orders him smitten on the mouth he calls him a whited wall, then apologizes for speaking evil of the ruler of the people. Perceiving that the council mixes Sadducees, who deny resurrection, angel, and spirit, with Pharisees, who confess both, Paul declares himself a Pharisee on trial for the hope and resurrection of the dead, and the council splits so violently that the chief captain rescues him. That night the Lord stands by Paul, promising that as he has testified at Jerusalem he must bear witness also at Rome. More than forty Jews bind themselves under a curse not to eat or drink until they kill Paul and plan to ambush him at a pretended council inquiry, but Paul's sister's son overhears and reports it, and the chief captain sends him by night to Felix the governor at Caesarea with an escort of soldiers and a letter finding nothing worthy of death or bonds in him.",
    context:"Paul answers the council in Jerusalem, and after a murder plot is uncovered the chief captain sends him by night under guard to Felix the governor at Caesarea.",
    keyVerses:[
      { ref:"Acts 23:1", text:"And Paul, earnestly beholding the council, said, Men and brethren, I have lived in all good conscience before God until this day." },
      { ref:"Acts 23:8", text:"For the Sadducees say that there is no resurrection, neither angel, nor spirit: but the Pharisees confess both." },
      { ref:"Acts 23:11", text:"And the night following the Lord stood by him, and said, Be of good cheer, Paul: for as thou hast testified of me in Jerusalem, so must thou bear witness also at Rome." }
    ],
    takeaway:"Be of good cheer: the Lord stands by His servants, confirming that their appointed work will be finished, whatever plots oppose it.",
    quiz:[
      { q:"Who overheard and reported the conspiracy of more than forty men against Paul?", choices:["Paul's sister's son","A temple guard","The high priest's servant","Felix's secretary"], a:0, why:"Paul's sister's son heard of their lying in wait, went into the castle, and told Paul, who had him bring the information to the chief captain." },
      { q:"How did Paul divide the council that was trying him?", choices:["By refusing to answer any questions","By calling the chief captain into the chamber","By declaring himself a Pharisee tried for the hope and resurrection of the dead, which the Sadducees deny","By accusing the high priest of theft"], a:2, why:"The Sadducees say there is no resurrection, neither angel, nor spirit, but the Pharisees confess both, so the scribes of the Pharisees' part declared they found no evil in him." },
      { q:"What assurance did the Lord give Paul the night after the council?", choices:["That he would never be bound again","That Jerusalem would believe his word","That the council would be dissolved","Be of good cheer: as thou hast testified of me in Jerusalem, so must thou bear witness also at Rome"], a:3, why:"The Lord stood by Paul and confirmed that his testimony would yet reach Rome, strengthening him before the murder plot unfolded." }
    ] },
  { n:24, summary:"Five days later the high priest Ananias comes down to Caesarea with an orator named Tertullus, who flatters governor Felix and accuses Paul of sedition, leading the sect of the Nazarenes, and profaning the temple. Paul cheerfully answers that only twelve days have passed since he went up to worship, that his accusers cannot prove their charges, and that what they call heresy is belief in the law and the prophets and in the resurrection of the dead, both of the just and unjust; he exercises himself to keep a conscience void of offence toward God and men. Felix, who knows the way accurately, defers the case, keeps Paul in mild custody, and hears him often with his wife Drusilla about faith in Christ. When Paul reasons of righteousness, temperance, and judgment to come, Felix trembles and postpones him, hoping for a bribe. After two years Felix is replaced by Porcius Festus and, to please the Jews, leaves Paul bound.",
    context:"At Caesarea, Paul answers before governor Felix the accusations brought by the high priest Ananias and the orator Tertullus, and remains in custody for two years.",
    keyVerses:[
      { ref:"Acts 24:15", text:"And have hope toward God, which they themselves also allow, that there shall be a resurrection of the dead, both of the just and unjust." },
      { ref:"Acts 24:16", text:"And herein do I exercise myself, to have always a conscience void of offence toward God, and toward men." },
      { ref:"Acts 24:25", text:"And as he reasoned of righteousness, temperance, and judgment to come, Felix trembled, and answered, Go thy way for this time; when I have a convenient season, I will call for thee." }
    ],
    takeaway:"Exercise yourself to keep a conscience void of offence toward God and men; do not put off faith until a convenient season.",
    quiz:[
      { q:"Who was the orator brought down with the high priest to accuse Paul before Felix?", choices:["Tertullus","Lysias","Sosthenes","Alexander"], a:1, why:"After five days Ananias the high priest descended with the elders, and with a certain orator named Tertullus, who informed the governor against Paul." },
      { q:"How did Felix react when Paul reasoned of righteousness, temperance, and judgment to come?", choices:["He was baptized the same hour","He ordered Paul released at once","He trembled and said, Go thy way for this time; when I have a convenient season, I will call for thee","He banished Paul from the province"], a:2, why:"Felix trembled at Paul's reasoning but postponed, and he had also hoped money would be given him, sending for Paul the oftener." },
      { q:"What did Paul confess about his worship and hope?", choices:["That Caesar was the head of the church","That he kept only the traditions of the elders","That resurrection applied to the just only","He worshipped after the way they call heresy, hoping for a resurrection of both just and unjust"], a:3, why:"Paul openly professed his faith in the resurrection of both the just and unjust and said he exercised himself to keep a conscience void of offence." }
    ] },
  { n:25, summary:"The new governor Festus goes up to Jerusalem after three days, and the Jewish leaders ask him to bring Paul to Jerusalem, intending to kill him on the way. Festus refuses and sits in judgment at Caesarea, where the accusers bring many grievous complaints they cannot prove; Paul maintains that he has offended nothing against the law of the Jews, the temple, or Caesar. When Festus, willing to please the Jews, proposes a trial at Jerusalem, Paul stands on his rights at Caesar's judgment seat and appeals unto Caesar; Festus confirms the appeal. Soon king Agrippa and Bernice visit, and Festus lays out the puzzle: the charges concern questions of their own religion and one Jesus, which was dead, whom Paul affirmed to be alive, and he has no certain thing to write to Caesar. Agrippa wishes to hear the man himself, and the next day Paul is brought before the assembly in great pomp.",
    context:"At Caesarea the new governor Festus hears Paul's case, and after appeals from the Jews Paul declares, I appeal unto Caesar, leading to a hearing before king Agrippa.",
    keyVerses:[
      { ref:"Acts 25:8", text:"While he answered for himself, Neither against the law of the Jews, neither against the temple, nor yet against Cæsar, have I offended any thing at all." },
      { ref:"Acts 25:11", text:"For if I be an offender, or have committed any thing worthy of death, I refuse not to die: but if there be none of these things whereof these accuse me, no man may deliver me unto them. I appeal unto Cæsar." },
      { ref:"Acts 25:19", text:"But had certain questions against him of their own superstition, and of one Jesus, which was dead, whom Paul affirmed to be alive." }
    ],
    takeaway:"Stand calmly on truth and lawful rights when accused; God can use even an appeal to Caesar to carry His witness forward.",
    quiz:[
      { q:"Who replaced Felix as governor of the province?", choices:["Porcius Festus","Gallio","Claudius Lysias","Sergius Paulus"], a:0, why:"Acts 24:27 closes with Felix being succeeded, and Acts 25:1 opens with Festus coming into the province, after three days going up to Jerusalem." },
      { q:"Why did Festus convene the hearing before king Agrippa?", choices:["Agrippa was Paul's chosen judge","Festus had no certain thing to write about the charges and wanted something to write after examination","Paul requested a royal audience","The Jews demanded Agrippa sit as judge"], a:1, why:"Festus told Agrippa the dispute concerned questions of their own religion and one Jesus, who was dead, whom Paul affirmed to be alive, and he had nothing certain to write." },
      { q:"What did Paul do when Festus proposed moving the trial to Jerusalem?", choices:["He agreed to go willingly","He confessed to the charges","He stood on his rights at Caesar's judgment seat and said, I appeal unto Cæsar","He escaped from the judgment hall"], a:2, why:"Paul refused to be delivered to the Jews, insisting he had done no wrong, and Festus confirmed, Hast thou appealed unto Cæsar? unto Cæsar shalt thou go." }
    ] },
  { n:26, summary:"Allowed to speak for himself, Paul tells king Agrippa that his case rests on the promise God made to the fathers: why should it be thought incredible that God raises the dead? Once a persecutor even to strange cities, Paul was stopped near Damascus by a light above the brightness of the sun, and the risen Jesus appointed him a minister and witness, sending him to open the Gentiles' eyes, to turn them from darkness to light and from the power of Satan unto God, that they might receive forgiveness of sins and inheritance among the sanctified. He was not disobedient to the heavenly vision but preached repentance in Damascus, Jerusalem, Judea, and among the Gentiles. Festus interrupts that much learning has made him mad, and Paul answers with words of truth and soberness, pressing Agrippa about the prophets. Agrippa replies that he is almost persuaded to be a Christian; privately the rulers agree that Paul has done nothing worthy of death or bonds and might have gone free had he not appealed to Caesar.",
    context:"In Caesarea before king Agrippa, Festus, and Bernice, Paul recounts his conversion and defends his testimony of the resurrection and his mission to the Gentiles.",
    keyVerses:[
      { ref:"Acts 26:8", text:"Why should it be thought a thing incredible with you, that God should raise the dead?" },
      { ref:"Acts 26:18", text:"To open their eyes, and to turn them from darkness to light, and from the power of Satan unto God, that they may receive forgiveness of sins, and inheritance among them which are sanctified by faith that is in me." },
      { ref:"Acts 26:28", text:"Then Agrippa said unto Paul, Almost thou persuadest me to be a Christian." }
    ],
    takeaway:"God sends witnesses to open eyes and turn people from darkness to light; obey the heavenly vision, for this thing was not done in a corner.",
    quiz:[
      { q:"What did king Agrippa say at the close of Paul's defense?", choices:["Almost thou persuadest me to be a Christian","Thou art beside thyself; much learning doth make thee mad","Away with such a fellow from the earth","I find no fault in this man"], a:0, why:"Agrippa answered Paul's appeal to the prophets with those words, and Paul wished that all who heard him were both almost and altogether such as he." },
      { q:"According to Paul's retelling, what mission did the risen Jesus give him by the Damascus road?", choices:["To restore the temple in Jerusalem","To become chief ruler of the Pharisees","To open the Gentiles' eyes and turn them from darkness to light and from the power of Satan unto God","To write letters to the synagogues"], a:2, why:"Jesus appeared to make Paul a minister and witness, sending him to the Gentiles so they might receive forgiveness of sins and inheritance among the sanctified." },
      { q:"How did Paul describe his response to the heavenly vision?", choices:["He obeyed only after years of delay","He kept the vision private his whole life","He asked to be released from it","I was not disobedient unto the heavenly vision"], a:3, why:"Paul told Agrippa he shewed first to Damascus, then Jerusalem and Judæa, and then to the Gentiles, that they should repent and turn to God." }
    ] },
  { n:27, summary:"Paul sails for Italy as a prisoner under the centurion Julius, with Aristarchus of Thessalonica accompanying. Sailing becomes dangerous after the fast, and at the Fair Havens Paul warns that the voyage will bring hurt and much damage, but the centurion trusts the shipmaster instead and they set out for Phenice. A tempest called Euroclydon seizes the ship; for many days neither sun nor stars appear, and all hope of being saved is lost. Paul then reports an angel's promise that he must stand before Caesar and that God has given him all who sail with him, urging all to be of good cheer and believe God. On the fourteenth night the sailors sound the depths and drop anchors; Paul keeps the sailors from escaping, persuades everyone to eat, and the ship of 276 souls finally runs aground on a place where two seas meet. Soldiers want to kill the prisoners, but the centurion, willing to save Paul, lets all swim or float to shore on boards, and they escape all safe to land.",
    context:"Sailing for Italy as a prisoner under the centurion Julius, Paul is caught in a two-week storm that wrecks the ship near Melita, though all 276 aboard survive.",
    keyVerses:[
      { ref:"Acts 27:23", text:"For there stood by me this night the angel of God, whose I am, and whom I serve," },
      { ref:"Acts 27:24", text:"Saying, Fear not, Paul; thou must be brought before Cæsar: and, lo, God hath given thee all them that sail with thee." },
      { ref:"Acts 27:25", text:"Wherefore, sirs, be of good cheer: for I believe God, that it shall be even as it was told me." }
    ],
    takeaway:"When God speaks through His servants, believing Him brings good cheer in the storm; His promises hold every soul safe to land.",
    quiz:[
      { q:"How many souls were aboard the storm-driven ship?", choices:["Forty","Two hundred threescore and sixteen","One hundred and twenty","Three thousand"], a:1, why:"Acts 27:37 counts the company at two hundred threescore and sixteen souls, all of whom escaped safe to land." },
      { q:"What message did the angel of God bring Paul during the storm?", choices:["That the ship and crew would be lost","That they should sail back to Crete","Fear not, Paul; thou must be brought before Cæsar: and God hath given thee all them that sail with thee","That Julius would release him at Myra"], a:2, why:"Paul told the frightened crew there would be no loss of any man's life, only of the ship, because the angel had promised him before God." },
      { q:"What warning did Paul give when the sailors tried to abandon ship?", choices:["That swimming to shore was certain death","That the anchors must stay down until summer","That the soldiers must chain the prisoners","Except these abide in the ship, ye cannot be saved"], a:3, why:"Paul told the centurion and soldiers that the sailors must stay aboard; the soldiers cut off the boat's ropes, and all escaped to land together." }
    ] },
  { n:28, summary:"The survivors land on Melita, whose people kindle a fire for the rain-soaked castaways. A viper fastens on Paul's hand, and when he suffers no harm the islanders decide he is a god; he heals the father of Publius, the island's chief man, and then the rest of the sick, and the party is honored and supplied for the voyage. After three months they sail by Syracuse and Rhegium to Puteoli, where brethren cheer them; at Rome, believers meet Paul as far as Appii Forum and he takes courage. Allowed to dwell by himself with a soldier, Paul calls the chief Jews, who say this sect is spoken against everywhere, and from morning to evening he persuades them concerning Jesus out of the law and the prophets. Some believe and some do not; Paul applies Isaiah's words about dull ears and declares that the salvation of God is sent unto the Gentiles, and they will hear it. For two whole years he preaches the kingdom of God in his hired house with all confidence, no man forbidding him.",
    context:"Shipwrecked on Melita and later arrived at Rome, Paul preaches to the Jewish leaders and then openly for two whole years from his own hired house.",
    keyVerses:[
      { ref:"Acts 28:5", text:"And he shook off the beast into the fire, and felt no harm." },
      { ref:"Acts 28:28", text:"Be it known therefore unto you, that the salvation of God is sent unto the Gentiles, and that they will hear it." },
      { ref:"Acts 28:31", text:"Preaching the kingdom of God, and teaching those things which concern the Lord Jesus Christ, with all confidence, no man forbidding him." }
    ],
    takeaway:"Nothing closes the work of God; His servants preach with all confidence, and the salvation of God is sent to all who will hear.",
    quiz:[
      { q:"On what island did Paul and his companions land after the shipwreck?", choices:["Cyprus","Melita","Crete","Sicily"], a:1, why:"Acts 28:1 says when they were escaped, then they knew that the island was called Melita." },
      { q:"What did the chief Jews at Rome say about the church when Paul called them?", choices:["That they had already condemned it","That all Rome had been baptized","This sect is spoken against everywhere, but we desire to hear what thou thinkest","That Paul's letters had convinced them all"], a:2, why:"They said they had received no letters from Judæa against him, but the sect was everywhere spoken against, so they appointed a day to hear him." },
      { q:"How does Acts describe Paul's ministry during his two years in Rome?", choices:["He was silenced until his trial","He escaped and sailed back east","He preached only to Roman officials","He dwelt in his hired house, received all who came, and preached the kingdom of God with all confidence"], a:3, why:"The book closes with Paul teaching those things which concern the Lord Jesus Christ with all confidence, no man forbidding him." }
    ] }
);
